#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 vector<int> findKDistantIndices(vector<int>& nums,int key,int k){vector<int> ans;int n=nums.size(),next=0;
  for(int i=0;i<n;++i){while(next<n&&(nums[next]!=key||next<i-k))++next;if(next<n&&next<=i+k)ans.push_back(i);}return ans;
 }
};
